if 'workspace' not in st.session_state:
    st.session_state.workspace = tempfile.mkdtemp(prefix='paperwise_')
    st.session_state.messages = []
    st.session_state.document = None
    st.session_state.selected_page = 1


def safe_error(exc):
    if isinstance(exc, DocumentError):
        return str(exc)
    text = str(exc).lower()
    if any(x in text for x in ['429', 'quota', 'rate limit']):
        return 'The research service has reached its usage limit. Please try again later or ask the administrator to check service access.'
    if any(x in text for x in ['401', '403', 'api key', 'unauthorized']):
        return 'The research service could not be accessed. Please ask the administrator to check the connection settings.'
    if '404' in text or 'not_found' in text:
        return 'The research service is unavailable. Please ask the administrator to update its configuration.'
    return 'We could not complete this request. Please try again. If the issue continues, contact the administrator.'


def answer_question(question, document):
    from langchain_google_genai import ChatGoogleGenerativeAI
    from langchain_core.prompts import ChatPromptTemplate
    from langchain_core.output_parsers import StrOutputParser
    llm = ChatGoogleGenerativeAI(model=os.getenv('GOOGLE_MODEL', 'gemini-3.5-flash-lite'), temperature=0)
    history = '\n'.join(f"{m['role']}: {m['content']}" for m in st.session_state.messages[-6:])
    search_question = question
    if history:
        rewrite = ChatPromptTemplate.from_messages([
            ('system', 'Rewrite the latest question as a standalone search question using the conversation only to resolve references. Do not answer it. Return only the question.'),
            ('human', 'Conversation:\n{history}\nLatest question: {question}')])
        search_question = (rewrite | llm | StrOutputParser()).invoke({'history': history, 'question': question})
    retriever = document['store'].as_retriever(search_type='mmr', search_kwargs={'k': 3, 'fetch_k': 10, 'lambda_mult': 0.5})
    docs = retriever.invoke(search_question)
    sources = [{'page': d.metadata.get('page', 0)+1, 'text': d.page_content} for d in docs]
    context = '\n\n'.join(f"[PDF page {s['page']}]\n{s['text']}" for s in sources)
    if not context.strip():
        return 'I could not find the answer in the document.', []
    prompt = ChatPromptTemplate.from_messages([
        ('system', SYSTEM_TEXT),
        ('human', 'Context:\n{context}\n\nConversation for reference only:\n{history}\n\nQuestion:\n{question}')])
    answer = (prompt | llm | StrOutputParser()).invoke({'context': context, 'history': history, 'question': question})
    return answer, sources


def select_page(page):
    st.session_state.selected_page = page


def show_sources(sources, key):
    if sources:
        with st.expander(f'View supporting passages · {len(sources)}'):
            for i, source in enumerate(sources):
                st.caption(f"PDF PAGE {source['page']}")
                st.write(source['text'])
                st.button('Read this page', key=f'source_{key}_{i}', on_click=select_page, args=(source['page'],))


with st.sidebar:
    st.markdown('<div class="brand">◈ Paper<span>wise</span></div>', unsafe_allow_html=True)
    st.caption('YOUR RESEARCH WORKSPACE')
    st.divider()
    st.markdown('#### Add a document')
    st.caption('Bring a paper. Start a conversation.')
    uploaded = st.file_uploader('Choose your research document', type=SUPPORTED, label_visibility='collapsed')
    st.caption('PDF, Office documents, text, spreadsheets and images · up to 25 MB')
    st.caption('Documents are sent to external AI services to prepare and answer your questions.')
    configured = bool(os.getenv('MISTRAL_API_KEY') and os.getenv('GOOGLE_API_KEY'))
    if not configured:
        st.info('Setup is required. Add your service credentials to the .env file, then restart the app.')
    if st.button('Open research workspace', type='primary', width='stretch', disabled=uploaded is None or not configured):
        bar = st.progress(0, text='Opening your document…')
        try:
            doc = prepare_document(uploaded.getvalue(), uploaded.name, st.session_state.workspace, lambda n, label: bar.progress(n, text=label))
            st.session_state.document = doc
            st.session_state.messages = []
            st.session_state.selected_page = 1
            st.rerun()
        except Exception as exc:
            logging.exception('Document preparation failed')
            st.error(safe_error(exc))
        finally:
            bar.empty()
    doc = st.session_state.document
    if doc:
        st.divider()
        st.markdown('#### Current document')
        st.write(doc['name'])
        st.caption(f"{doc['pages']} pages · Ready for questions")
        if st.button('Start a new conversation', width='stretch'):
            st.session_state.messages = []
            st.rerun()
        transcript = '\n\n'.join(f"{'You' if m['role']=='user' else 'Paperwise'}\n{m['content']}" + ('\n\nSupporting pages: '+', '.join(str(s['page']) for s in m.get('sources', [])) if m.get('sources') else '') for m in st.session_state.messages)
        st.download_button('Download conversation', transcript, file_name='research-notes.txt', mime='text/plain', disabled=not transcript, width='stretch')
    st.divider()
    st.markdown('<div class="note">Read with context.<br>Ask with curiosity.<br>Keep the evidence close.</div>', unsafe_allow_html=True)

st.markdown('<div class="eyebrow">Research, with a clearer perspective</div>', unsafe_allow_html=True)
st.markdown('<div class="hero"><div class="eyebrow">Your reading companion</div><h1>Less searching.<br>More understanding.</h1><p>Explore the ideas, methods and findings in your research. Ask a question and follow the evidence back to the page.</p></div>', unsafe_allow_html=True)

doc = st.session_state.document
if not doc:
    for col, number, title, description in zip(st.columns(3), ['01','02','03'], ['Bring your research', 'Ask better questions', 'Follow the evidence'], ['Upload a paper or document to create a focused reading workspace.', 'Unpack a method, clarify a concept or explore the reported findings.', 'Review supporting passages alongside the original document.']):
        with col:
            st.markdown(f'<div class="card"><span class="step">{number}</span><b>{title}</b><p>{description}</p></div>', unsafe_allow_html=True)
    st.markdown('<div class="empty"><h3>Your next insight starts with a document.</h3><p>Upload a file in the sidebar, then select Open research workspace.</p></div>', unsafe_allow_html=True)
    st.chat_input('Upload a document to begin…', disabled=True)
else:
    left, right = st.columns([1.25, 1], gap='large')
    with right:
        st.markdown('### Reading room')
        st.caption(doc['name'])
        if doc['converted']:
            st.caption('Reading copy · Page references refer to this converted PDF.')
        if doc['blank_pages']:
            st.warning('Some pages have no selectable text and may not be represented in answers.')
        page = st.number_input('PDF page', min_value=1, max_value=doc['pages'], step=1, key='selected_page')
        # Render only the selected page, avoiding browser PDF plugin differences.
        import pymupdf
        with pymupdf.open(doc['pdf']) as pdf:
            pixmap = pdf[page-1].get_pixmap(matrix=pymupdf.Matrix(1.5, 1.5))
            st.image(pixmap.tobytes('png'), width='stretch')
        st.download_button('Download reading copy', Path(doc['pdf']).read_bytes(), file_name=Path(doc['name']).stem+'.pdf', mime='application/pdf', width='stretch')
    with left:
        st.markdown('### Discuss this document')
        st.caption('Answers grounded in your document, with passages to review.')
        query = None
        if not st.session_state.messages:
            for label, question in [('Research focus', 'What research problem does this document address?'), ('Methods & approach', 'Explain the methodology described in this document.'), ('Findings & limitations', 'What findings and limitations are reported in this document?')]:
                if st.button(label, width='stretch'):
                    query = question
        for index, message in enumerate(st.session_state.messages):
            with st.chat_message(message['role']):
                st.markdown(message['content'])
                show_sources(message.get('sources'), index)
        typed = st.chat_input('Ask about the ideas, methods or findings…', max_chars=4000)
        query = typed or query
        if query:
            with st.chat_message('user'):
                st.write(query)
            try:
                with st.spinner('Reviewing the relevant passages…'):
                    answer, sources = answer_question(query, doc)
                st.session_state.messages.extend([{'role': 'user', 'content': query}, {'role': 'assistant', 'content': answer, 'sources': sources}])
                st.rerun()
            except Exception as exc:
                logging.exception('Question failed')
                st.error(safe_error(exc))
        st.caption('Check important claims against the source. Answers reflect the passages found for your question.')


